import Foundation

enum H264SequenceParameters {
    static func signalNoReordering(_ parameterSet: Data) -> Data {
        let nal = [UInt8](parameterSet)
        // Only rewrite the progressive Baseline SPS generated by our encoder, with no existing VUI.
        guard (5...512).contains(nal.count), nal[0] & 0x1f == 7, nal[1] == 66 else { return parameterSet }
        var reader = SPSBits(nal)
        guard reader.skipValues(2), let order = reader.unsigned(), order == 0 || order == 2 else { return parameterSet }
        if order == 0 && !reader.skipValues(1) { return parameterSet }
        guard let references = reader.unsigned(), references <= 16,
              reader.bit() != nil, reader.skipValues(2), reader.bit() == 1,
              reader.bit() != nil, let cropped = reader.bit() else { return parameterSet }
        if cropped == 1 && !reader.skipValues(4) { return parameterSet }
        let end = reader.position
        guard reader.bit() == 0, reader.bit() == 1, reader.values[reader.position...].allSatisfy({ $0 == 0 }) else {
            return parameterSet
        }

        // Advertise the encoder's no-B-frame contract to decoders that infer a reorder buffer from the level.
        var bits = Array(reader.values[..<end])
        bits.append(1) // vui_parameters_present_flag
        bits.append(contentsOf: repeatElement(0, count: 8)) // Optional VUI sections through pic_struct_present_flag.
        bits.append(contentsOf: [1, 1]) // bitstream_restriction_flag, motion_vectors_over_pic_boundaries_flag
        for value in [0, 0, 16, 16, 0, max(1, references)] {
            let code = String(value + 1, radix: 2)
            bits.append(contentsOf: repeatElement(0, count: code.count - 1))
            bits.append(contentsOf: code.map { $0 == "1" ? 1 : 0 })
        }
        bits.append(1) // rbsp_stop_one_bit
        bits.append(contentsOf: repeatElement(0, count: (8 - bits.count % 8) % 8))
        var result = Data()
        var zeros = 0
        for offset in stride(from: 0, to: bits.count, by: 8) {
            let byte = bits[offset..<offset + 8].reduce(UInt8(0)) { ($0 << 1) | $1 }
            if zeros == 2 && byte <= 3 {
                result.append(3)
                zeros = 0
            }
            result.append(byte)
            zeros = byte == 0 ? zeros + 1 : 0
        }
        return result
    }

    private struct SPSBits {
        var values = [UInt8]()
        var position = 32 // NAL header, profile, constraints, and level.

        init(_ nal: [UInt8]) {
            var zeros = 0
            for byte in nal {
                if zeros == 2 && byte == 3 {
                    zeros = 0
                    continue
                }
                for shift in (0..<8).reversed() { values.append((byte >> shift) & 1) }
                zeros = byte == 0 ? zeros + 1 : 0
            }
        }

        mutating func bit() -> UInt8? {
            guard position < values.count else { return nil }
            defer { position += 1 }
            return values[position]
        }

        mutating func unsigned() -> Int? {
            var length = 0
            while let head = bit() {
                if head == 1 {
                    var number = 1
                    for _ in 0..<length {
                        guard let next = bit() else { return nil }
                        number = (number << 1) | Int(next)
                    }
                    return number - 1
                }
                length += 1
                if length > 16 { return nil }
            }
            return nil
        }

        mutating func skipValues(_ count: Int) -> Bool {
            for _ in 0..<count {
                if unsigned() == nil { return false }
            }
            return true
        }
    }
}
